-- ============================================================
-- Schema: CHILE | Engine: MySQL 8
-- PII columns marked with -- [PII]
-- ============================================================

CREATE DATABASE IF NOT EXISTS demo_chile;
USE demo_chile;

DROP TABLE IF EXISTS `clientes`;
CREATE TABLE `clientes` (
    `id` INT,
    `nombre` VARCHAR(100),
    `apellido` VARCHAR(100),
    `email` VARCHAR(150),
    `telefono` VARCHAR(30),
    `rut` VARCHAR(25),
    `fecha_nacimiento` DATE,
    `genero` VARCHAR(10),
    `estado_civil` VARCHAR(20),
    `direccion_linea1` VARCHAR(200),
    `direccion_linea2` VARCHAR(100),
    `ciudad` VARCHAR(100),
    `region` VARCHAR(100),
    `codigo_postal` VARCHAR(15),
    `pais` VARCHAR(50)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `empleados`;
CREATE TABLE `empleados` (
    `id` INT,
    `nombre` VARCHAR(100),
    `apellido` VARCHAR(100),
    `email_corporativo` VARCHAR(150),
    `email_personal` VARCHAR(150),
    `telefono` VARCHAR(30),
    `rut` VARCHAR(25),
    `fecha_nacimiento` DATE,
    `cargo` VARCHAR(100),
    `departamento` VARCHAR(100),
    `salario` DECIMAL(12,2),
    `fecha_ingreso` DATE,
    `direccion_linea1` VARCHAR(200),
    `direccion_linea2` VARCHAR(100),
    `ciudad` VARCHAR(100),
    `codigo_postal` VARCHAR(15),
    `banco` VARCHAR(100),
    `cuenta_bancaria` VARCHAR(30)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `cuentas_bancarias`;
CREATE TABLE `cuentas_bancarias` (
    `id` INT,
    `numero_cuenta` VARCHAR(30),
    `sucursal` VARCHAR(10),
    `tipo_cuenta` VARCHAR(30),
    `saldo` DECIMAL(14,2),
    `limite` DECIMAL(14,2),
    `titular` VARCHAR(200),
    `rut_titular` VARCHAR(25),
    `banco` VARCHAR(100),
    `fecha_apertura` DATE,
    `estado` VARCHAR(20)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `tarjetas_credito`;
CREATE TABLE `tarjetas_credito` (
    `id` INT,
    `numero_tarjeta` VARCHAR(25),
    `nombre_titular` VARCHAR(200),
    `vencimiento` VARCHAR(8),
    `red` VARCHAR(30),
    `limite` DECIMAL(12,2),
    `factura_actual` DECIMAL(12,2),
    `estado` VARCHAR(20),
    `rut_titular` VARCHAR(25)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `pedidos`;
CREATE TABLE `pedidos` (
    `id` INT,
    `numero_pedido` VARCHAR(20),
    `fecha_pedido` DATE,
    `nombre_cliente` VARCHAR(200),
    `rut_cliente` VARCHAR(25),
    `monto_total` DECIMAL(12,2),
    `estado` VARCHAR(30),
    `direccion_entrega` VARCHAR(200),
    `complemento_entrega` VARCHAR(100),
    `ciudad_entrega` VARCHAR(100),
    `codigo_postal_entrega` VARCHAR(15)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `historiales_medicos`;
CREATE TABLE `historiales_medicos` (
    `id` INT,
    `nombre_paciente` VARCHAR(200),
    `rut_paciente` VARCHAR(25),
    `fecha_nacimiento` DATE,
    `tipo_sangre` VARCHAR(5),
    `diagnostico` VARCHAR(200),
    `medicamentos` VARCHAR(200),
    `medico_responsable` VARCHAR(200),
    `seguro_medico` VARCHAR(100),
    `fecha_consulta` DATE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `proveedores`;
CREATE TABLE `proveedores` (
    `id` INT,
    `nombre_empresa` VARCHAR(200),
    `rut_empresa` VARCHAR(25),
    `nombre_contacto` VARCHAR(200),
    `email` VARCHAR(150),
    `telefono` VARCHAR(30),
    `direccion` VARCHAR(200),
    `ciudad` VARCHAR(100),
    `codigo_postal` VARCHAR(15),
    `segmento` VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `transacciones`;
CREATE TABLE `transacciones` (
    `id` INT,
    `fecha_transaccion` DATETIME,
    `tipo` VARCHAR(50),
    `monto` DECIMAL(14,2),
    `cuenta_origen` VARCHAR(30),
    `cuenta_destino` VARCHAR(30),
    `descripcion` VARCHAR(200),
    `estado` VARCHAR(30),
    `ip_origen` VARCHAR(50),
    `ubicacion` VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `logs_acceso`;
CREATE TABLE `logs_acceso` (
    `id` INT,
    `fecha_hora` DATETIME,
    `usuario_id` INT,
    `email_usuario` VARCHAR(150),
    `ip_address` VARCHAR(50),
    `user_agent` VARCHAR(300),
    `accion` VARCHAR(50),
    `recurso` VARCHAR(200),
    `codigo_estado` INT,
    `ubicacion` VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `polizas_seguro`;
CREATE TABLE `polizas_seguro` (
    `id` INT,
    `numero_poliza` VARCHAR(20),
    `nombre_titular` VARCHAR(200),
    `rut_titular` VARCHAR(25),
    `fecha_nacimiento` DATE,
    `tipo_seguro` VARCHAR(50),
    `cobertura` DECIMAL(14,2),
    `prima_mensual` DECIMAL(10,2),
    `fecha_inicio` DATE,
    `fecha_fin` DATE,
    `beneficiario` VARCHAR(200)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `contratos`;
CREATE TABLE `contratos` (
    `id` INT,
    `numero_contrato` VARCHAR(20),
    `nombre_empresa` VARCHAR(200),
    `rut_empresa_empresa` VARCHAR(25),
    `nombre_contacto` VARCHAR(200),
    `email_contacto` VARCHAR(150),
    `telefono_contacto` VARCHAR(30),
    `monto_contrato` DECIMAL(16,2),
    `fecha_inicio` DATE,
    `fecha_fin` DATE,
    `estado` VARCHAR(20)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `leads_marketing`;
CREATE TABLE `leads_marketing` (
    `id` INT,
    `nombre` VARCHAR(100),
    `apellido` VARCHAR(100),
    `email` VARCHAR(150),
    `telefono` VARCHAR(30),
    `empresa` VARCHAR(200),
    `cargo` VARCHAR(100),
    `fuente` VARCHAR(50),
    `fecha_registro` DATE,
    `estado` VARCHAR(30),
    `interes` VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

